    {
      id: 27,
      title: "Unit 27",
      storyTitle: "The Earl of Shining",
      story: "In the village of Hampton, there was an old soldier named Michael, but he was known to the world as the Earl of Shining. Michael was once an expert archer and a great fighter. In fact, his skills seemed to be hereditary; all the people in his ancestry were famous warriors. However, he was getting old and no longer wished to fight.\n\nOne day, he was in the forest hunting prey when he saw a beautiful prophet singing a hymn. She said, “ Michael, an evil army is involved in a conspiracy to take over Hampton. You ’re the only one who can defeat them and stop the tyranny. The village needs you!” Michael replied, “ But I’m too old to fight! I’m not confident that I can do it.” The prophet said, “You must try.\n\nI will even make a potion to increase your strength.” The prophet took out a bottle and a funnel. She poured some vinegar and garlic into the bottle. Next, she added some seasoning and sodium and shook it up. Michael smelled the potion. “Wow, this is fragrant,” he said in a sarcastic tone. He inverted the bottle and drank the whole potion. He immediately felt stronger. “ I’ll try my best,” he promised.\n\nMichael rode his horse to a hill top, where he could see the village of Hampton below. He saw the evil tyrant and his men marching in a procession through the town. Michael charged down the hill and into the village. An enemy deputy officer shouted, “ He looks as strong as an ox!” It was an apt analogy. Michael grabbed the officer and threw him across the street with one arm.\n\nThe rest of the officers screamed and rode away, and their army followed. The prophet re appeared. Michael said, “ It’s a good thing you gave me the potion.” She replied, “ But Michael, the potion was fake! Your strength really came from having confidence! Michael realized he really was still great. He just needed to believe in himself.",
      words: [
        { id: "27-1", word: "analogy", ipa: "/əˈnælədʒi/", pos: "n.", definition: "An analogy is a connect i on made between things to show that they are similar.", example: "The doctor made an analogy between the human heart and a water pump.", examples: ["The teacher used an analogy to explain the idea.", "There is an analogy between the heart and a pump."], vi: "phép so sánh, sự tương đồng", forms: ["analogy"] },
        { id: "27-2", word: "ancestry", ipa: "/ˈænsestri/", pos: "n.", definition: "A person’s ancestry is the series of people from whom a person descended.", example: "M/estudied our ancestry and found out that we are related to royalty.", examples: ["She is proud of her Irish ancestry.", "He traced his ancestry back to the 1600s."], vi: "tổ tiên, dòng dõi", forms: ["ancestry"] },
        { id: "27-3", word: "archer", ipa: "/ˈɑːrtʃər/", pos: "n.", definition: "An archer is a person who uses a bow and arrows.", example: "The expert archer hit the target every time.", examples: ["The archer hit the center of the target.", "The archers waited for the king’s order."], vi: "cung thủ", forms: ["archers", "archer"] },
        { id: "27-4", word: "conspiracy", ipa: "/kənˈspɪrəsi/", pos: "n.", definition: "A conspiracy is a secret plan made by a group of people to do something illegal.", example: "Some people think that there was a conspiracy to kill American president John F. Kennedy.", examples: ["They were arrested for a conspiracy against the king.", "Some people believe in a conspiracy about the moon landing."], vi: "âm mưu", forms: ["conspiracy"] },
        { id: "27-5", word: "deputy", ipa: "/ˈdepjuti/", pos: "n.", definition: "A deputy is the second-highest-ran king person in a business or government.", example: "While the sheriff was ill, the deputy took over his duties.", examples: ["The deputy mayor opened the new library.", "The sheriff and his deputy arrived at the house."], vi: "phó, người thay mặt", forms: ["deputy"] },
        { id: "27-6", word: "earl", ipa: "/ɜːrl/", pos: "n.", definition: "An earl is a nobleman from Britain.", example: "The Earl of Canterbury lived in a huge mansion.", examples: ["The earl lived in a large castle.", "He was given the title of earl by the king."], vi: "bá tước", forms: ["earl"] },
        { id: "27-7", word: "fragrant", ipa: "/ˈfreɪɡrənt/", pos: "adj.", definition: "When something is fragrant, it has a pleasant smell.", example: "The girl picked delicious berries and fragrant flowers.", examples: ["The garden is full of fragrant roses.", "The kitchen was fragrant with fresh bread."], vi: "thơm ngát", forms: ["fragrant"] },
        { id: "27-8", word: "funnel", ipa: "/ˈfʌnl/", pos: "n.", definition: "A funnel is an object with a wide top and a narrow bottom for pouring liquids.", example: "The worker used a funnel when he poured the oil into the engine.", examples: ["She used a funnel to pour oil into the bottle.", "Smoke rose from the ship’s funnel."], vi: "cái phễu", forms: ["funnel"] },
        { id: "27-9", word: "hereditary", ipa: "/həˈredɪteri/", pos: "adj.", definition: "If something is hereditary, it is a trait passed onto children from their parents.", example: "The hereditary disease affected three generations of children.", examples: ["The disease is hereditary.", "He holds a hereditary title."], vi: "di truyền, cha truyền con nối", forms: ["hereditary"] },
        { id: "27-10", word: "hymn", ipa: "/hɪm/", pos: "n.", definition: "A hymn is a religious song that often praises a god.", example: "The book was filled with hymns that the worshippers sang.", examples: ["The choir sang a hymn.", "They learned the hymn in church."], vi: "bài thánh ca", forms: ["hymns", "hymn"] },
        { id: "27-11", word: "invert", ipa: "/ɪnˈvɜːrt/", pos: "v.", definition: "To invert something means to turn it up side down.", example: "He inverted the bicycle to make repairs on the wheels.", examples: ["Invert the bowl to remove the cake.", "He inverted the glass over the spider."], vi: "lật ngược", forms: ["inverted", "invert"] },
        { id: "27-12", word: "prey", ipa: "/preɪ/", pos: "n.", definition: "Prey is the animals that are hunted and eaten by another creature.", example: "The lion ran as fast as he could to catch his prey.", examples: ["The lion followed its prey through the grass.", "Mice are the prey of owls."], vi: "con mồi", forms: ["prey"] },
        { id: "27-13", word: "procession", ipa: "/prəˈseʃn/", pos: "n.", definition: "A procession is a group of people who walk or drive in a line during a public event.", example: "The procession all celebrated when they reached the end.", examples: ["A long procession walked through the streets.", "The funeral procession moved slowly."], vi: "đoàn rước, đoàn diễu hành", forms: ["procession"] },
        { id: "27-14", word: "prophet", ipa: "/ˈprɑːfɪt/", pos: "n.", definition: "A prophet is a person chosen by a god to give the god’s message to people.", example: "Harold believed that he was one of the prophets of his god.", examples: ["The prophet warned the people of danger.", "Many prophets lived in ancient times."], vi: "nhà tiên tri", forms: ["prophets", "prophet"] },
        { id: "27-15", word: "sarcastic", ipa: "/sɑːrˈkæstɪk/", pos: "adj.", definition: "When something is sarcastic, it is the opposite of what is actually meant.", example: "She hurt her mother’s feelings with her constant sarcastic remarks.", examples: ["“Nice job,” he said in a sarcastic voice.", "Her sarcastic remarks hurt his feelings."], vi: "mỉa mai", forms: ["sarcastic"] },
        { id: "27-16", word: "seasoning", ipa: "/ˈsiːzənɪŋ/", pos: "n.", definition: "Seasoning is a mix of salt, herbs, and spices that improves the taste of food.", example: "This steak tastes bland. Maybe I’ll add some seasoning to it.", examples: ["Add some seasoning to the soup.", "The chicken needs more seasoning."], vi: "gia vị", forms: ["seasoning"] },
        { id: "27-17", word: "sodium", ipa: "/ˈsoʊdiəm/", pos: "n.", definition: "Sodium is an element that can be used to make substances such as salt.", example: "Sodium and ch lo ride combine to make table salt.", examples: ["Salt contains sodium.", "Too much sodium is bad for your health."], vi: "nguyên tố natri", forms: ["sodium"] },
        { id: "27-18", word: "tyranny", ipa: "/ˈtɪrəni/", pos: "n.", definition: "A tyranny is a cruel and unfair government in which one person has power.", example: "His tyranny was impossible to live under.", examples: ["The people rose up against tyranny.", "Life under tyranny was full of fear."], vi: "chế độ độc tài", forms: ["tyranny"] },
        { id: "27-19", word: "tyrant", ipa: "/ˈtaɪrənt/", pos: "n.", definition: "A tyrant is someone who treats people in a cruel, harsh, and unfair way.", example: "Our boss is a tyrant. He makes us work long hours for little pay.", examples: ["The tyrant ruled with cruelty.", "The people were glad when the tyrant died."], vi: "bạo chúa", forms: ["tyrant"] },
        { id: "27-20", word: "vinegar", ipa: "/ˈvɪnɪɡər/", pos: "n.", definition: "Vinegar is a strong liquid made from sour wine that is used in cooking.", example: "Be careful because too much vinegar will ruin the recipe.", examples: ["She put vinegar and oil on the salad.", "Vinegar is made from sour wine."], vi: "giấm", forms: ["vinegar"] }
      ]
    },
    /* ======================================================================
       UNIT 28
       ====================================================================== */
    {
      id: 28,
      title: "Unit 28",
      storyTitle: "The Lord and the Farmers",
      story: "A wealthy lord was renovating his mansion. He had added another story to his home with large windows that over looked the farmers’ pastures on the eastern border of his land. Around the mansion, he then erected a great wall. He built an arch for the gate out of huge slabs of stone. The lord was overjoyed with the addition to his home.\n\nHowever, one day while he was sitting on the terrace, some farmers knocked at his door. He invited them in. Despite his hospitality, the farmers appeared to be in a foul mood. “Why are you so upset?” the lord asked.\n\nOne farmer replied, “That is actually the reason for our visit.” He then handed the lord a petition. It alleged that the shadow cast by the mansion was harming their pastures. “Your mansion now casts a shadow over several hectares of our land,” the farmer explained. “The turf in the shadow has died, and our cattle now have less grass to eat.”\n\n“ It is too late for me to revise my plans,” the lord answered. “You will just have to live with the change.”\n\nHis reply only heightened the farmers’ anger. They left, but they assembled that night outside the mansion’s gate. They planned to destroy the mansion. The lord’s servants tried to defend the house, but the farmers outnumbered them.\n\nThe servants fled, and the farmers rushed into the mansion and set it on fire. Everyone got out of the house, and there were no casualties. However, the fire soon spread from the house to the adjoining pastures that belonged to the farmers.\n\nBoth sides’ properties were destroyed. The lord and the farmers were sorry for their actions. The lord promised to pay for the burned pastures, and the farmers promised to re build the mansion. They had learned that when you fight, both sides lose.",
      words: [
        { id: "28-1", word: "adjoining", ipa: "/əˈdʒɔɪnɪŋ/", pos: "adj.", definition: "If something is adjoining, it is next to or joined with a building, or room.", example: "I couldn’t sleep because the people in the adjoining room were loud.", examples: ["We stayed in adjoining rooms.", "The adjoining fields belong to my uncle."], vi: "liền kề, tiếp giáp", forms: ["adjoining"] },
        { id: "28-2", word: "allege", ipa: "/əˈledʒ/", pos: "v.", definition: "To allege something is to say that it is true without offering proof.", example: "The little girl had alleged that her older brother hid her favorite doll.", examples: ["The police allege that he stole the car.", "She alleged that he had lied."], vi: "cáo buộc, khẳng định (chưa có bằng chứng)", forms: ["alleged", "allege"] },
        { id: "28-3", word: "arch", ipa: "/ɑːrtʃ/", pos: "n.", definition: "An arch is a curved opening formed under a structure such as a bridge or door way.", example: "The arch of the bridge was not high enough for the tall boat to pass underneath.", examples: ["The bridge has a stone arch.", "They walked under the arch into the garden."], vi: "vòm", forms: ["arch"] },
        { id: "28-4", word: "assemble", ipa: "/əˈsembl/", pos: "v.", definition: "To assemble means to get together in one place.", example: "The parents assembled to discuss ways to improve their children’s education.", examples: ["The students assembled in the hall.", "He assembled the bike in an hour."], vi: "tập hợp, lắp ráp", forms: ["assembled", "assemble"] },
        { id: "28-5", word: "casualty", ipa: "/ˈkæʒuəlti/", pos: "n.", definition: "A casualty is a person killed or in ju red in a war or an accident.", example: "The only casualty in the car accident was a woman who broke her arm.", examples: ["There were many casualties in the accident.", "The soldier was a casualty of the war."], vi: "người thương vong", forms: ["casualties", "casualty"] },
        { id: "28-6", word: "erect", ipa: "/ɪˈrekt/", pos: "v.", definition: "To erect something means to build it.", example: "The king erected two to we rs on the north and south sides of his castle.", examples: ["They erected a tent in the field.", "The town erected a statue of the mayor."], vi: "dựng lên", forms: ["erected", "erect"] },
        { id: "28-7", word: "foul", ipa: "/faʊl/", pos: "adj.", definition: "If something is foul, then it is not pleasant or enjoy able.", example: "He wouldn’t let his dog drink from the water because it had a foul smell.", examples: ["There was a foul smell in the kitchen.", "The weather was foul all week."], vi: "hôi thối, khó chịu", forms: ["foul"] },
        { id: "28-8", word: "hectare", ipa: "/ˈhekter/", pos: "n.", definition: "A hectare is a unit of me a sure equal to 10, ooo square meters.", example: "His family farm covered many hectares.", examples: ["The farm covers fifty hectares.", "A hectare is ten thousand square meters."], vi: "héc-ta", forms: ["hectares", "hectare"] },
        { id: "28-9", word: "heighten", ipa: "/ˈhaɪtn/", pos: "v.", definition: "To heighten an emotion means to increase the intensity of it.", example: "The pleasant music heightened their enjoy me nt of the wonderful dinner.", examples: ["The dark clouds heightened our fear.", "The music heightened the feeling of excitement."], vi: "làm tăng, nâng cao", forms: ["heightened", "heighten"] },
        { id: "28-10", word: "hospitality", ipa: "/ˌhɑːspɪˈtæləti/", pos: "n.", definition: "Hospitality is friendly behavior and entertain me nt given to guests or strange rs.", example: "The travelers were amazed at the hospitality given them by the hotel’s staff.", examples: ["Thank you for your kind hospitality.", "The village is famous for its hospitality."], vi: "lòng hiếu khách", forms: ["hospitality"] },
        { id: "28-11", word: "mansion", ipa: "/ˈmænʃn/", pos: "n.", definition: "A mansion is a large and expensive home.", example: "The mansion had thirty bed rooms, two kitchens, and a pool.", examples: ["The rich man lived in a huge mansion.", "The mansion had twenty rooms."], vi: "biệt thự lớn", forms: ["mansion"] },
        { id: "28-12", word: "outnumber", ipa: "/ˌaʊtˈnʌmbər/", pos: "v.", definition: "To outnumber a group means to have a greater number than it.", example: "The girls outnumbered the boys at the school by four to one.", examples: ["Girls outnumber boys in the class.", "The enemy outnumbered us three to one."], vi: "đông hơn", forms: ["outnumbered", "outnumber"] },
        { id: "28-13", word: "overjoyed", ipa: "/ˌoʊvərˈdʒɔɪd/", pos: "adj.", definition: "If someone is overjoyed, then they are extremely happy.", example: "He was overjoyed by the news of his promotion.", examples: ["She was overjoyed to see her family.", "The children were overjoyed by the news."], vi: "vui mừng khôn xiết", forms: ["overjoyed"] },
        { id: "28-14", word: "pasture", ipa: "/ˈpæstʃər/", pos: "n.", definition: "A pasture is an area of land covered with grass for animals to use as food.", example: "The sheep were taken to a pasture where there was more grass.", examples: ["The cows grazed in the pasture.", "The sheep were moved to a new pasture."], vi: "đồng cỏ chăn thả", forms: ["pastures", "pasture"] },
        { id: "28-15", word: "petition", ipa: "/pəˈtɪʃn/", pos: "n.", definition: "A petition is a written request asking an authority to do something.", example: "The citizens all signed a petition asking the mayor to repair the sidewalks.", examples: ["They signed a petition to save the park.", "The petition asked the mayor to build a bridge."], vi: "đơn kiến nghị", forms: ["petition"] },
        { id: "28-16", word: "renovate", ipa: "/ˈrenəveɪt/", pos: "v.", definition: "To renovate a building means to repair it or build new structures on it.", example: "The old fire station was renovated into an apartment building.", examples: ["They renovated the old kitchen.", "The hotel was renovated last year."], vi: "cải tạo, tân trang", forms: ["renovating", "renovated", "renovate"] },
        { id: "28-17", word: "revise", ipa: "/rɪˈvaɪz/", pos: "v.", definition: "To revise something means to change or update it to make it better.", example: "When the editor discovered certain facts were wrong, he revised the book.", examples: ["He revised his essay before handing it in.", "She is revising for the exam."], vi: "sửa đổi, ôn tập", forms: ["revising", "revised", "revise"] },
        { id: "28-18", word: "slab", ipa: "/slæb/", pos: "n.", definition: "A slab is a large, thick, flat piece of stone, concrete, metal, or wood.", example: "I looked at various slabs of stone to decorate my house.", examples: ["The path was made of stone slabs.", "He cut a slab of cake."], vi: "tấm, phiến", forms: ["slabs", "slab"] },
        { id: "28-19", word: "terrace", ipa: "/ˈterəs/", pos: "n.", definition: "A terrace is an open area that is connected to a house or an apartment.", example: "In the afternoons, she liked to sit on the terrace and check her email.", examples: ["We had breakfast on the terrace.", "The house has a terrace overlooking the sea."], vi: "sân thượng, bậc thềm", forms: ["terrace"] },
        { id: "28-20", word: "turf", ipa: "/tɜːrf/", pos: "n.", definition: "Turf is a section of grass and the dirt in which it grows.", example: "After the game, the turf looked ragged.", examples: ["The players ran onto the turf.", "He cut a piece of turf from the lawn."], vi: "thảm cỏ, mảnh đất cỏ", forms: ["turf"] }
      ]
    },
    /* ======================================================================
       UNIT 29
       ====================================================================== */
    {
      id: 29,
      title: "Unit 29",
      storyTitle: "The Shortcut",
      story: "A truck driver was driving cargo from the outback to the coast. His load was comprised of many types of ore. He needed a huge truck to carry its bulk to a ship waiting at a pier on the country’s eastern coast. At the border between two counties, he’d have to pay a tariff on the cargo. However, he could keep his money if he avoided the station at the border. He worried about getting in trouble for not paying the tariff, but the thought of extra money outweighed this concern.\n\nHe took out his road map. To his surprise, it depicted a small road that had a dual advantage. It not only avoided the border station but also was a shorter route to the coast. He decided to take the shortcut.\n\nHowever, along his journey, he soon ran into problems. First, he had to cross a small wooden bridge. His truck weighed too much for the bridge. It was analogous to an elephant trying to stand on a tree branch. The bridge started to break as the truck crossed, and the trailer tilted to the right. Fortunately, the truck made it safely across, but most of the ore fell into the river below.\n\nNext, it was a very hot day. The thermometer read over 100 degrees Fahrenheit. The truck’s engine became too hot, so the driver parked it in the shade of a grove of trees until it cooled down.\n\nLater, he took a wrong turn. He stopped and took out his binoculars. He scanned his surroundings and eventually discovered a land mark that led him back to the proper route. Finally, he arrived at the pier, but the ship wasn’t there. When he asked about the ship’s whereabouts, a man said that it had left thirty minutes ago. He had not fulfilled his duty. He realized then the paradox of the shortcut. The shortest route can be the longest, and vice versa, a long route may be the fastest.",
      words: [
        { id: "29-1", word: "analogous", ipa: "/əˈnæləɡəs/", pos: "adj.", definition: "If something is analogous to another thing, then it is like it in certain ways.", example: "The relationship with his teacher was analogous to that of a son and mother.", examples: ["The two situations are analogous.", "The heart is analogous to a pump."], vi: "tương tự", forms: ["analogous"] },
        { id: "29-2", word: "binoculars", ipa: "/bɪˈnɑːkjələrz/", pos: "n.", definition: "Binoculars are a device used for seeing things that are far away.", example: "He could see the ship on the horizon only if he used his binoculars.", examples: ["He watched the birds through binoculars.", "Take your binoculars to see the animals."], vi: "ống nhòm", forms: ["binoculars"] },
        { id: "29-3", word: "bulk", ipa: "/bʌlk/", pos: "n.", definition: "The bulk of something is its great size.", example: "The large elephant moved its bulk with legs as strong as tree trunks.", examples: ["The bulk of the work is already done.", "We buy rice in bulk."], vi: "phần lớn, khối lượng lớn", forms: ["bulk"] },
        { id: "29-4", word: "comprise", ipa: "/kəmˈpraɪz/", pos: "v.", definition: "If something comprises something else, it consists of or is made up of it.", example: "Our school’s football team is mostly comprised with seniors.", examples: ["The team comprises ten players.", "The book comprises five chapters."], vi: "bao gồm", forms: ["comprised", "comprises", "comprise"] },
        { id: "29-5", word: "depict", ipa: "/dɪˈpɪkt/", pos: "v.", definition: "To depict something means to show or portray it, often using art.", example: "The statue’s face depicted the general’s determination and courage.", examples: ["The painting depicts a village in winter.", "The film depicts the life of a farmer."], vi: "miêu tả, vẽ", forms: ["depicted", "depicts", "depict"] },
        { id: "29-6", word: "dual", ipa: "/ˈduːəl/", pos: "adj.", definition: "If something is dual, then it is made up of two parts.", example: "The room had a dual function. It was a living room, but at night it was a bed room.", examples: ["The car has dual controls.", "He holds dual citizenship."], vi: "kép, đôi", forms: ["dual"] },
        { id: "29-7", word: "Fahrenheit", ipa: "/ˈfærənhaɪt/", pos: "n.", definition: "Fahrenheit temperature is a scale where water freezes at 32° and boils at 212°.", example: "When the temperature dropped to 32° Fahrenheit, it started snowing.", examples: ["Water boils at 212 degrees Fahrenheit.", "It was ninety degrees Fahrenheit outside."], vi: "độ F", forms: ["Fahrenheit"] },
        { id: "29-8", word: "fulfill", ipa: "/fʊlˈfɪl/", pos: "v.", definition: "To fulfill something means to achieve or finish it.", example: "The professor did not fulfill his promise not to miss a single class.", examples: ["She fulfilled her dream of becoming a pilot.", "He fulfilled his promise to visit us."], vi: "hoàn thành, thực hiện", forms: ["fulfilled", "fulfill"] },
        { id: "29-9", word: "grove", ipa: "/ɡroʊv/", pos: "n.", definition: "A grove is a small group of trees.", example: "All the trees in this grove are apple trees.", examples: ["We had a picnic in an olive grove.", "A grove of oak trees stood by the lake."], vi: "lùm cây, khu rừng nhỏ", forms: ["grove"] },
        { id: "29-10", word: "ore", ipa: "/ɔːr/", pos: "n.", definition: "Ore is the raw form of rock or material from which a valuable metal is taken.", example: "The factory melted the ore and used it to make iron products.", examples: ["Iron ore is found in the mountains.", "They mine copper ore in this region."], vi: "quặng", forms: ["ore"] },
        { id: "29-11", word: "outback", ipa: "/ˈaʊtbæk/", pos: "n.", definition: "The outback is the wild in land region of Australia where very few people live.", example: "Many Australian farmers use the outback to raise cattle.", examples: ["They drove across the Australian outback.", "Few people live in the outback."], vi: "vùng hẻo lánh (Úc)", forms: ["outback"] },
        { id: "29-12", word: "outweigh", ipa: "/ˌaʊtˈweɪ/", pos: "v.", definition: "To outweigh something means to exceed it in value, amount, or importance.", example: "Finding a warm place to sleep outweighed the need to find something to eat.", examples: ["The benefits outweigh the risks.", "The cost of the trip outweighed the fun."], vi: "nặng hơn, quan trọng hơn", forms: ["outweighed", "outweigh"] },
        { id: "29-13", word: "paradox", ipa: "/ˈpærədɑːks/", pos: "n.", definition: "A paradox is a true statement or real event that seems illogical.", example: "The paradox of her work was that the less she worked, the more she got done.", examples: ["It is a paradox that the richest country has many poor people.", "The story is full of paradoxes."], vi: "nghịch lý", forms: ["paradoxes", "paradox"] },
        { id: "29-14", word: "pier", ipa: "/pɪr/", pos: "n.", definition: "A pier is a structure that extends into a body of water.", example: "If you want to catch bigger fish, then go to the far end of the pier.", examples: ["We walked to the end of the pier.", "Fishermen sat on the pier."], vi: "bến tàu, cầu tàu", forms: ["pier"] },
        { id: "29-15", word: "shortcut", ipa: "/ˈʃɔːrtkʌt/", pos: "n.", definition: "A shortcut is a route that is shorter than the main route.", example: "We got to the house first because we took a shortcut through the forest.", examples: ["We took a shortcut through the park.", "There is no shortcut to success."], vi: "đường tắt", forms: ["shortcut"] },
        { id: "29-16", word: "tariff", ipa: "/ˈtærɪf/", pos: "n.", definition: "A tariff is a tax or fee paid on certain imports or exports.", example: "Our tariff on imported wool makes foreign wool more expensive.", examples: ["The country put a tariff on foreign cars.", "High tariffs make imports expensive."], vi: "thuế quan", forms: ["tariffs", "tariff"] },
        { id: "29-17", word: "thermometer", ipa: "/θərˈmɑːmɪtər/", pos: "n.", definition: "A thermometer is a device that measures temperature.", example: "The thermometer outside the window indicated that it was a hot day today.", examples: ["The nurse put a thermometer in his mouth.", "The thermometer shows thirty degrees."], vi: "nhiệt kế", forms: ["thermometer"] },
        { id: "29-18", word: "tilt", ipa: "/tɪlt/", pos: "v.", definition: "To tilt something means to tip it into a sloping position.", example: "She tilted her glass and almost spilled some of the wine inside.", examples: ["Tilt your head back.", "The boat tilted to one side."], vi: "nghiêng", forms: ["tilted", "tilt"] },
        { id: "29-19", word: "vice versa", ipa: "/ˌvaɪs ˈvɜːrsə/", pos: "adv.", definition: "If a statement is vice versa, then its two main ideas are switched with one another.", example: "Students learn from their teachers, and vice versa.", examples: ["I help him, and vice versa.", "Adults learn from children and vice versa."], vi: "ngược lại", forms: ["vice versa"] },
        { id: "29-20", word: "whereabouts", ipa: "/ˈwerəbaʊts/", pos: "n.", definition: "The whereabouts of someone or something is the place where they are.", example: "The police looked for the lost dog, but its whereabouts were still unknown.", examples: ["His whereabouts are unknown.", "The police asked about her whereabouts that night."], vi: "tung tích, nơi ở", forms: ["whereabouts"] }
      ]
    },
    /* ======================================================================
       UNIT 30
       ====================================================================== */
    {
      id: 30,
      title: "Unit 30",
      storyTitle: "The Mad Hatter",
      story: "One morning, Lucas sat outside with his grandfather. They looked past the gravel road that led to a natural reservoir on the delta. On the other side of the water, there was a cottage. “ Does a ghost live there?” Lucas asked.\n\n“ No, a mad hatter lives there,” said his grandfather. Lucas didn’t know what a mad hatter was, but the image of a scary man haunted him.\n\nLater, Lucas went for a walk in the forest. He collected pieces of amber and granite that he found on the ground. He looked at the moss on the trees and watched a bird peck at the ground. But the forest was like a maze. Soon, Lucas was lost.\n\nLucas heard some body behind him. He wanted to run away, but he fell. He had a streak of blood on his shirt and some pebbles stuck in his skin. Then a man appeared. “ I will take you home. First, let’s get you cleaned up,” he said.\n\nLucas followed him. When they arrived at the cottage, he realized the man was the mad hatter!\n\nHe sat down inside. It smelled like charcoal, but it looked like a normal house. The man brought Lucas back some medicine.\n\n“ It’s a bit old, but it’s not expired,” the man said.\n\nWhile Lucas cleaned his cut, the man washed the blood out of his shirt with detergent. Lucas asked, “Are you a mad hatter?”\n\nThe man laughed and replied, “That’s a euphemism for a crazy person. Actually, I’m pretty normal. I’m a columnist fora newspaper,” said the man. He pointed to his credentials which hung on the wall.\n\nLucas could hear the crickets outside. It was getting dark, so he asked, “ Could you take me home now?”\n\nThe man said yes. Lucas was surprised that people thought the man was crazy. He was actually very courteous. Maybe Lucas should have a more liberal attitude. Next time, Lucas wouldn’t make judgments about people without getting to know them first.",
      words: [
        { id: "30-1", word: "amber", ipa: "/ˈæmbər/", pos: "n.", definition: "Amber is a hard, yellowish material that comes from trees.", example: "The necklace was made from pieces of amber.", examples: ["The necklace was made of amber.", "A small insect was trapped in the amber."], vi: "hổ phách", forms: ["amber"] },
        { id: "30-2", word: "charcoal", ipa: "/ˈtʃɑːrkoʊl/", pos: "n.", definition: "Charcoal is a black material that is used as fuel for fire.", example: "There was burnt charcoal left on the ground from an old fire.", examples: ["We cooked the meat over charcoal.", "The artist drew with charcoal."], vi: "than củi", forms: ["charcoal"] },
        { id: "30-3", word: "columnist", ipa: "/ˈkɑːləmnɪst/", pos: "n.", definition: "A columnist is a writer who creates articles about a particular subject.", example: "The columnist won praise for his articles about life on the farm.", examples: ["The columnist writes about food every week.", "He is a famous newspaper columnist."], vi: "người viết chuyên mục", forms: ["columnist"] },
        { id: "30-4", word: "courteous", ipa: "/ˈkɜːrtiəs/", pos: "adj.", definition: "When someone is courteous, they are polite and respectful.", example: "The mother asked her family to be courteous to their guests.", examples: ["The waiter was courteous to all guests.", "She gave a courteous reply."], vi: "lịch sự, nhã nhặn", forms: ["courteous"] },
        { id: "30-5", word: "credentials", ipa: "/krɪˈdenʃlz/", pos: "n.", definition: "Credentials are the proof of someone’s experience or ability to do something.", example: "The mechanic hung his credentials on his office wall.", examples: ["The doctor has excellent credentials.", "He showed his credentials at the door."], vi: "bằng cấp, chứng chỉ", forms: ["credentials"] },
        { id: "30-6", word: "crickets", ipa: "/ˈkrɪkɪts/", pos: "n.", definition: "A cricket is an insect that makes loud noises, usually at night.", example: "In the country, we could see the stars and hear the crickets at night.", examples: ["We heard crickets in the grass at night.", "Crickets are small jumping insects."], vi: "con dế", forms: ["crickets"] },
        { id: "30-7", word: "delta", ipa: "/ˈdeltə/", pos: "n.", definition: "A delta is flat area where a river splits into smaller ri ve rs that flow into the sea.", example: "The archeologists found many ancient materials in the delta of the Nile River.", examples: ["Many people farm rice in the river delta.", "The Nile delta is very fertile."], vi: "đồng bằng châu thổ", forms: ["delta"] },
        { id: "30-8", word: "detergent", ipa: "/dɪˈtɜːrdʒənt/", pos: "n.", definition: "Detergent is soap that is used to clean clothes or dishes.", example: "My brother added too much detergent to the wash, and bubbles got all over the floor.", examples: ["She added detergent to the washing machine.", "This detergent smells like lemons."], vi: "bột giặt, chất tẩy rửa", forms: ["detergent"] },
        { id: "30-9", word: "euphemism", ipa: "/ˈjuːfəmɪzəm/", pos: "n.", definition: "A euphemism is a term that is used in place of a mean or unpleasant word.", example: "“ Window maintenance officer” is a euphemism for a window was her.", examples: ["“Passed away” is a euphemism for “died.”", "He used a euphemism to describe the failure."], vi: "cách nói giảm nói tránh", forms: ["euphemism"] },
        { id: "30-10", word: "expire", ipa: "/ɪkˈspaɪər/", pos: "v.", definition: "To expire is to no longer be effective because its use has come to an end.", example: "The man’s driver’s license was going to expire in two days.", examples: ["My passport expires next month.", "The offer expires on Friday."], vi: "hết hạn", forms: ["expired", "expires", "expire"] },
        { id: "30-11", word: "granite", ipa: "/ˈɡrænɪt/", pos: "n.", definition: "Granite is a very hard type of rock that is often black or pink.", example: "The kitchen counter was made of granite.", examples: ["The kitchen has a granite counter.", "The mountain is made of granite."], vi: "đá hoa cương", forms: ["granite"] },
        { id: "30-12", word: "gravel", ipa: "/ˈɡrævl/", pos: "n.", definition: "Gravel is a combination of small stones mixed with sand.", example: "The ground around the swing set was covered with gravel.", examples: ["The path was covered with gravel.", "Cars crunched over the gravel drive."], vi: "sỏi, đá dăm", forms: ["gravel"] },
        { id: "30-13", word: "haunt", ipa: "/hɔːnt/", pos: "v.", definition: "To haunt is to cause problems or negative thoughts over a long period of time.", example: "His thoughts about his scary dream haunted him for weeks.", examples: ["The memory of the accident haunted him.", "They say a ghost haunts the old house."], vi: "ám ảnh", forms: ["haunted", "haunts", "haunt"] },
        { id: "30-14", word: "liberal", ipa: "/ˈlɪbərəl/", pos: "adj.", definition: "When someone is liberal, they accept different ideas and people.", example: "My grandparents a ren’t as liberal as my parents.", examples: ["She has liberal views on education.", "The school has a liberal attitude to dress."], vi: "cởi mở, phóng khoáng", forms: ["liberal"] },
        { id: "30-15", word: "maze", ipa: "/meɪz/", pos: "n.", definition: "A maze is a system of paths that is complicated and easy to get lost in.", example: "We got lost in the maze in the garden.", examples: ["The children got lost in the maze.", "The old city is a maze of narrow streets."], vi: "mê cung", forms: ["maze"] },
        { id: "30-16", word: "moss", ipa: "/mɔːs/", pos: "n.", definition: "Moss is a small green or yellow plant that grows on wet dirt, rocks, or tree trunks.", example: "Be careful not to slip on the moss that’s cove ring those rocks.", examples: ["Moss grows on the north side of trees.", "The rocks were covered with green moss."], vi: "rêu", forms: ["moss"] },
        { id: "30-17", word: "peck", ipa: "/pek/", pos: "v.", definition: "When a bird pecks, it bites or hits something with its beak.", example: "The birds pecked at the seeds on the ground.", examples: ["The chickens pecked at the corn.", "A bird pecked at the window."], vi: "mổ", forms: ["pecked", "pecks", "peck"] },
        { id: "30-18", word: "pebble", ipa: "/ˈpebl/", pos: "n.", definition: "A pebble is a small, round stone.", example: "We threw pebbles into the lake to make the water splash.", examples: ["He picked up a smooth pebble.", "The beach was covered with pebbles."], vi: "viên sỏi", forms: ["pebbles", "pebble"] },
        { id: "30-19", word: "reservoir", ipa: "/ˈrezərvwɑːr/", pos: "n.", definition: "A reservoir is a place for storing water for a town to use.", example: "If it doesn’t rain soon, the reservoir is going to dry up completely.", examples: ["The city gets its water from a reservoir.", "The reservoir is low after the dry summer."], vi: "hồ chứa nước", forms: ["reservoir"] },
        { id: "30-20", word: "streak", ipa: "/striːk/", pos: "n.", definition: "A streak is a long, thin mark that is easy to see.", example: "Her hair was brown except for a streak which she dyed blonde.", examples: ["There was a streak of mud on his face.", "She has a streak of white in her hair."], vi: "vệt, sọc", forms: ["streak"] }
      ]
    }
